INSERT INTO sop_step_visual(attachment_id,image_width,image_height,schema_version,guide_items,detection_regions,created_by,updated_by)
    VALUES(#{attachmentId},#{width},#{height},1,#{guides},#{regions},#{actor},#{actor})
    ON DUPLICATE KEY UPDATE image_width=#{width},image_height=#{height},guide_items=#{guides},detection_regions=#{regions},updated_by=#{actor}
